SELECT 
  FROM growth_goals
 WHERE streamer_id = #{streamerId}

   AND status = #{status}

 ORDER BY period_end, id

SELECT 
  FROM growth_goals
 WHERE streamer_id = #{streamerId}
   AND id = #{goalId}

SELECT 
  FROM growth_goals
 WHERE streamer_id = #{streamerId}
   AND id = #{goalId}
 FOR UPDATE

SELECT id, growth_goal_id, generation_id, title, content FROM growth_actions WHERE growth_goal_id IN
#{id}
ORDER BY growth_goal_id, id

WITH selected_goals AS ( SELECT * FROM growth_goals WHERE streamer_id = #{streamerId} AND id IN
#{id}
), eligible AS ( SELECT s.streamer_id, s.started_at, s.ended_at, r.avg_viewers, r.total_chat FROM broadcast_sessions s JOIN reports r ON r.session_id = s.id WHERE s.streamer_id = #{streamerId} AND s.status = 'ENDED' AND r.status IN ('COMPLETED', 'PARTIAL') ), per_goal AS ( SELECT g.id AS growth_goal_id, g.period_start, g.period_end, e.started_at, e.avg_viewers, e.total_chat, CASE WHEN e.started_at IS NULL OR e.ended_at IS NULL THEN 0 ELSE GREATEST( extract(epoch FROM LEAST( e.ended_at, (g.period_end + 1)::timestamp AT TIME ZONE 'UTC' ) - GREATEST( e.started_at, g.period_start::timestamp AT TIME ZONE 'UTC' ) ), 0 ) END AS overlap_seconds FROM selected_goals g LEFT JOIN eligible e ON e.started_at < ( (g.period_end + 1)::timestamp AT TIME ZONE 'UTC' ) AND e.ended_at > ( g.period_start::timestamp AT TIME ZONE 'UTC' ) ) SELECT growth_goal_id, round(( sum(avg_viewers * overlap_seconds) FILTER (WHERE avg_viewers IS NOT NULL) / nullif( sum(overlap_seconds) FILTER (WHERE avg_viewers IS NOT NULL), 0 ) )::numeric, 2 ) AS average_viewers, coalesce(sum(total_chat) FILTER ( WHERE started_at >= ( period_start::timestamp AT TIME ZONE 'UTC' ) AND started_at < ( (period_end + 1)::timestamp AT TIME ZONE 'UTC' ) ), 0)::numeric AS total_chat, round( (coalesce(sum(overlap_seconds), 0) / 60.0)::numeric, 2 ) AS broadcast_minutes, round( count(started_at) FILTER ( WHERE started_at >= ( period_start::timestamp AT TIME ZONE 'UTC' ) AND started_at < ( (period_end + 1)::timestamp AT TIME ZONE 'UTC' ) )::numeric / ((period_end - period_start + 1)::numeric / 7), 2 ) AS broadcasts_per_week FROM per_goal GROUP BY growth_goal_id, period_start, period_end ORDER BY growth_goal_id

SELECT 1
  FROM (
        SELECT pg_advisory_xact_lock(
            hashtextextended(
                concat(#{streamerId}::text, ':', #{metricType}::text),
                0
            )
        )
  ) locked

SELECT EXISTS (
    SELECT 1
      FROM growth_goals
     WHERE streamer_id = #{streamerId}
       AND metric_type = #{metricType}
       AND status = 'ACTIVE'
       AND period_start <= #{periodEnd}
       AND period_end >= #{periodStart}

       AND id <> #{excludedGoalId}

)

