INSERT INTO growth_action_generations (
    growth_goal_id, source_report_id, goal_revision, trigger_type,
    status, prompt_version, idempotency_key, requested_at
) VALUES (
    #{goalId}, #{sourceReportId}, #{revision}, #{triggerType},
    #{status}, #{promptVersion}, #{idempotencyKey}, #{requestedAt}
)
ON CONFLICT (idempotency_key)
DO UPDATE SET idempotency_key = EXCLUDED.idempotency_key
RETURNING id

mapper.update:
UPDATE growth_action_generations
   SET status = 'SUPERSEDED', completed_at = now()
 WHERE growth_goal_id = #{goalId}
   AND goal_revision < #{revision}
   AND status IN ('WAITING_FOR_DATA', 'PENDING', 'PROCESSING')

UPDATE growth_action_generations
   SET status = 'SUPERSEDED', completed_at = now()
 WHERE growth_goal_id = #{goalId}
   AND id <> #{generationId}
   AND status IN ('WAITING_FOR_DATA', 'PENDING', 'PROCESSING')

UPDATE growth_action_generations
   SET status = 'PENDING', error_code = #{errorCode}
 WHERE id = #{generationId}
   AND status = 'PROCESSING'

UPDATE growth_action_generations
   SET status = 'FAILED', completed_at = #{completedAt}, error_code = #{errorCode}
 WHERE id = #{generationId}
   AND status IN ('PENDING', 'PROCESSING')
